parameters.initialMessages:
Informe um JSON contendo o nivel e as areas_desbloqueadas do jogador.
Exemplo: 
{
  "nivel": 2,
  "areas_desbloqueadas": [
    "Vila de Elden",
    "Floresta Sombria"
  ]
}

parameters.jsCode:
// 1) Recebe os itens do nó anterior
let docs = $input.all().map(i => i.json);

if (Array.isArray(docs[0])) {
  docs = docs[0];
}

// 2) Limpa o texto extraído
const clean = (s = '') =>
  s.replace(/\u00ad/g, '')
   .replace(/[ \t]+\n/g, '\n')
   .replace(/\n{3,}/g, '\n\n')
   .trim();

// 3) Prepara os chunks estruturados por seções/fichas
const out = [];

for (const d of docs) {
  const fullText = clean(d.text || '');

  if (!fullText) continue;

  // Divide o texto pelos divisores visuais dos seus documentos
  const sections = fullText.split(/-------------------------------------------------------------------------------|===============================================================================/);

  let chunkIdx = 1;

  for (const sec of sections) {
    const cleanSection = sec.trim();

    // Filtra cabeçalhos curtos ou blocos vazios
    if (cleanSection.length > 30) {
      out.push({
        json: {
          text: cleanSection,
          metadata: {
            titulo: d.titulo || 'Documento de Eldoria',
            author: d.autor || 'Grupo de Agentes de IA — Optativa',
            ano: d.ano || 2026,
            source: d.link_pdf || '',
            pages: d.numpages || null,
            pdf_version: d.info?.PDFFormatVersion || null,
            chunk: chunkIdx++
          }
        }
      });
    }
  }
}

return out;

// Pega dinamicamente o primeiro buffer binário disponível, evitando o erro de nome
const binaryKey = Object.keys($input.item.binary || {})[0];
if (!binaryKey) {
  throw new Error("Nenhum arquivo binário foi encontrado na entrada do nó.");
}

const binaryData = await this.helpers.getBinaryDataBuffer(0, binaryKey);
const raw = binaryData.toString('utf-8');

// Converte o texto do JSON em objeto
const data = JSON.parse(raw);

// Mapeia cada artigo do JSON como um item separado para o fluxo
return data.artigos.map((a, i) => ({
  json: {
    id: i + 1,
    titulo: a.titulo,
    autor: a.autor,
    ano: a.ano,
    link_pdf: a.link_pdf
  }
}));

// Pega o texto gerado pelo agente de IA com segurança
let inputData = $input.item?.json || {};
let rawText = inputData.output || inputData.text || Object.values(inputData)[0];

// Se mesmo assim vier vazio, retorna um objeto padrão para não quebrar o fluxo
if (!rawText || typeof rawText !== 'string') {
  return [{ json: { error: "Nenhum texto recebido do agente", raw: inputData } }];
}

// Remove as crases de markdown (```json e ```) se elas existirem
let cleanText = rawText.replace(/```json/g, "").replace(/```/g, "").trim();

// Transforma a string limpa num objeto JSON real
let jsonOutput;
try {
  jsonOutput = JSON.parse(cleanText);
} catch (e) {
  jsonOutput = { text: cleanText }; // Se não for um JSON válido, guarda como texto puro
}

// Retorna o JSON limpo para o fluxo do n8n
return [{ json: jsonOutput }];
